def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    char_index = {ch: i for i, ch in enumerate(alphabet)}
    width = len(alphabet)

    transitions = [[-1] * width]
    failure = [0]
    forbidden = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = char_index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * width)
                failure.append(0)
                forbidden.append(False)
            state = transitions[state][c]
        forbidden[state] = True

    queue = deque()
    for c in range(width):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        fallback = failure[state]
        forbidden[state] |= forbidden[fallback]

        for c in range(width):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[fallback][c]
            else:
                failure[child] = transitions[fallback][c]
                queue.append(child)

    valid = {
        state: i
        for i, state in enumerate(
            state for state in range(len(transitions))
            if not forbidden[state]
        )
    }
    size = len(valid)
    matrix = [[0] * size for _ in range(size)]

    for state, i in valid.items():
        for target in transitions[state]:
            if not forbidden[target]:
                matrix[i][valid[target]] += 1

    vector = [0] * size
    vector[valid[0]] = 1

    while n:
        if n & 1:
            result = [0] * size
            for i, ways in enumerate(vector):
                if ways:
                    for j, count in enumerate(matrix[i]):
                        result[j] += ways * count
            vector = [value % MOD for value in result]

        n >>= 1
        if not n:
            break

        squared = []
        for row in matrix:
            result = [0] * size
            for k, coefficient in enumerate(row):
                if coefficient:
                    for j, value in enumerate(matrix[k]):
                        result[j] += coefficient * value
            squared.append([value % MOD for value in result])
        matrix = squared

    return sum(vector) % MOD
